  <script>
    (function () {
      const button = document.getElementById("theme-toggle");
      const root = document.documentElement;

      function updateButton(theme) {
        const night = theme === "dark";
        button.textContent = night ? "☀" : "☾";
        button.setAttribute("aria-label", night ? "Switch to day mode" : "Switch to night mode");
        button.setAttribute("title", night ? "Switch to day mode" : "Switch to night mode");
      }

      updateButton(root.dataset.theme || "light");

      button.addEventListener("click", function () {
        const next = root.dataset.theme === "dark" ? "light" : "dark";
        root.dataset.theme = next;
        updateButton(next);
        try {
          localStorage.setItem("upb-theme", next);
        } catch (_) {
          /* Theme remains active for this page view if storage is unavailable. */
        }
      });
    }());
  </script>
