  (() => {
    const button = document.getElementById("theme-toggle");
    const root = document.documentElement;
    function sync(theme) {
      button.textContent = theme === "dark" ? "☀" : "☾";
      button.setAttribute("aria-label", theme === "dark" ? "Switch to day mode" : "Switch to night mode");
      button.title = theme === "dark" ? "Switch to day mode" : "Switch to night mode";
    }
    sync(root.dataset.theme || "light");
    button.addEventListener("click", () => {
      const theme = root.dataset.theme === "dark" ? "light" : "dark";
      root.dataset.theme = theme;
      sync(theme);
      try { localStorage.setItem("upb-theme", theme); } catch (error) {}
    });
  })();
</script>
